    size_t a1_n = 0;
    const char *a1 = JS_ToCStringLen(ctx, &a1_n, argv[1]);
    if (!a1) return JS_EXCEPTION;
    uint64_t r = (uint64_t)gearbox_send((uint32_t)a0, a1, (uint32_t)a1_n);
